def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """

    # Convert both inputs to float for comparison, except when they are already floats
    try:
        a = float(a)
    except ValueError:
        pass

    try:
        b = float(b)
    except ValueError:
        pass

    # Check if either value is a string and attempt to convert it to a float
    if isinstance(a, str):
        a = float(a.replace(',', '.'))
    if isinstance(b, str):
        b = float(b.replace(',', '.'))

    # Compare the values and return the appropriate result
    if a == b:
        return None
    elif a > b:
        return a
    else:
        return b

